import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, float, positionGeometry } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  group.userData.cleanup = () => {};

  // --- Backdrop plane ---
  const backdropGeo = new ctx.THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    transparent: false,
    side: ctx.THREE.DoubleSide,
  });
  backdropMat.colorNode = (() => {
    const uvy = uv().y;
    const c0 = vec3(0.043, 0.043, 0.063);  // #0b0b10
    const c1 = vec3(0.063, 0.063, 0.090);  // #101017
    const c2 = vec3(0.086, 0.086, 0.114);  // #16161d
    const t = mix(c0, c1, smoothstep(0.0, 0.65, uvy));
    return mix(t, c2, smoothstep(0.65, 1.0, uvy));
  })();
  const backdrop = new ctx.THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -3;
  group.add(backdrop);

  // --- Contact shadow plane ---
  const shadowGeo = new ctx.THREE.PlaneGeometry(2.6, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    side: ctx.THREE.DoubleSide,
  });
  shadowMat.colorNode = (() => {
    const uv2 = uv();
    const aspect = 2.6 / 1.2;
    const dx = uv2.x - 0.5;
    const dy = (uv2.y - 0.5) * aspect;
    const dist = float(dx * dx + dy * dy);
    const alpha = smoothstep(0.25, 0.0, dist);
    return vec3(0.0, 0.0, 0.0, alpha.mul(0.5));
  })();
  shadowMat.opacityNode = (() => {
    const uv2 = uv();
    const aspect = 2.6 / 1.2;
    const dx = uv2.x - 0.5;
    const dy = (uv2.y - 0.5) * aspect;
    const dist = float(dx * dx + dy * dy);
    return smoothstep(0.25, 0.0, dist).mul(0.5);
  })();
  const shadow = new ctx.THREE.Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -1.2, 0.01);
  group.add(shadow);

  // --- Lights ---
  const ambient = new ctx.THREE.AmbientLight(0xffffff, 0.6);
  group.add(ambient);
  const keyLight = new ctx.THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1, 1, 1);
  group.add(keyLight);
  const rimLight = new ctx.THREE.DirectionalLight(0xffffff, 0.8);
  rimLight.position.set(-1, 1, -1);
  group.add(rimLight);

  // --- Text ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  items.forEach((item) => {
    const fontSize = item.typography?.fontSize ?? 18;
    const color = item.role === 'headline' ? '#e8ecf2' : '#e8ecf2';
    const text = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color,
      align: 'center',
      letterSpacing: item.role === 'caption' ? 0.08 : -0.005,
    });
    if (item.role === 'headline') {
      text.position.set(0, -1.7, 0.1);
    } else if (item.role === 'caption') {
      text.position.set(0, -2.1, 0.1);
    }
    group.add(text);
  });

  // --- Gear mechanism (loaded async) ---
  const gearGroup = new ctx.THREE.Group();
  group.add(gearGroup);

  let gearPrimary = null;
  let gearSecondary = null;
  let gearMaterials = null;

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene;
    // Assume first mesh is the primary gear
    const primaryMesh = scene.children.find((c) => c.isMesh);
    if (!primaryMesh) return;

    // Clone material for modification
    const mat = new MeshPhysicalNodeMaterial();
    mat.copy(primaryMesh.material);
    mat.roughness = 0.5;
    mat.metalness = 0.55;
    mat.clearcoat = 0.2;
    mat.clearcoatRoughness = 0.3;
    mat.anisotropy = 0.7;
    mat.anisotropyRotation = 0;
    mat.needsUpdate = true;

    // Primary gear
    gearPrimary = primaryMesh.clone();
    gearPrimary.material = mat;
    gearPrimary.scale.set(1.6, 1.6, 1.6); // normalized to 1.6-unit diameter
    gearPrimary.position.set(0, 0, 0);
    gearGroup.add(gearPrimary);

    // Secondary gear (clone)
    gearSecondary = primaryMesh.clone();
    gearSecondary.material = mat.clone();
    gearSecondary.scale.set(0.9, 0.9, 0.9);
    gearSecondary.position.set(1.15, 0.35, -0.1);
    gearGroup.add(gearSecondary);

    // Jewel pivot sphere
    const jewelMat = new MeshPhysicalNodeMaterial({
      color: 0xff2a38,
      transmission: 0.6,
      ior: 1.76,
      emissive: 0xff2a38,
      emissiveIntensity: 1.8,
      roughness: 0.2,
      metalness: 0.0,
    });
    const jewelGeo = new ctx.THREE.SphereGeometry(0.12, 32, 32);
    const jewel = new ctx.THREE.Mesh(jewelGeo, jewelMat);
    jewel.position.set(0, 0, 0);
    gearGroup.add(jewel);

    // Arbor shafts
    const shaftMat = new MeshPhysicalNodeMaterial({
      color: 0x16161d,
      roughness: 0.8,
      metalness: 0.2,
    });
    const shaftGeo = new ctx.THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
    const shaft1 = new ctx.THREE.Mesh(shaftGeo, shaftMat);
    shaft1.position.set(0, 0, 0);
    shaft1.rotation.x = Math.PI / 2;
    gearGroup.add(shaft1);

    const shaft2 = new ctx.THREE.Mesh(shaftGeo.clone(), shaftMat);
    shaft2.position.set(1.15, 0.35, -0.1);
    shaft2.rotation.x = Math.PI / 2;
    gearGroup.add(shaft2);

    // Start gear rotation animation
    const ticker = (time, delta) => {
      if (gearPrimary) gearPrimary.rotation.z += 0.08 * delta;
      if (gearSecondary) gearSecondary.rotation.z -= 0.142 * delta;
    };
    gsap.ticker.add(ticker);

    // Extend cleanup
    const origCleanup = group.userData.cleanup;
    group.userData.cleanup = () => {
      gsap.ticker.remove(ticker);
      origCleanup();
      // Dispose materials and geometries if needed
      jewelMat.dispose();
      shaftMat.dispose();
      jewelGeo.dispose();
      shaftGeo.dispose();
      mat.dispose();
      gearPrimary?.material?.dispose();
      gearSecondary?.material?.dispose();
    };
  }).catch((err) => {
    console.error('Failed to load gear mesh:', err);
  });

  // --- Cinematic primitive: orbit ---
  const result = ctx.primitives['orbit'](group, { speed: 0.08, radius: 0.2 });
  const origCleanup = group.userData.cleanup;
  group.userData.cleanup = () => {
    result.cleanup();
    origCleanup();
  };

  // --- Event handlers (none) ---
  group.userData.handlers = {};

  return group;
}
